(()=>{
  'use strict';
  const GAME='aeCayKheVuonTriThuc_v1', STORY='aeCayKheMucJourney_v1';
  const $=id=>document.getElementById(id);
  const safeParse=(key,fallback={})=>{try{return JSON.parse(localStorage.getItem(key)||'null')||fallback}catch(e){return fallback}};
  const game=()=>safeParse(GAME,{});
  const expansion=()=>safeParse('aeCayKheExpansion_v1',{});
  const bugs=()=>Array.isArray(expansion().bugs)?expansion().bugs:[];
  const deliveries=s=>(+s.deliveryCount||0)+(+s.orderDeliveries||0);

  
  function talk(speaker,avatar,mood,text,prompt,choiceA,replyA,choiceB,replyB,bad,feedback,replySpeaker='Mực',replyAvatar='🐈‍⬛'){
    return {speaker,avatar,mood,text,prompt,options:[
      {label:choiceA,accepted:true,metric:'evidence',playerText:choiceA,reply:replyA,replySpeaker,replyAvatar},
      {label:choiceB,accepted:true,metric:'teamwork',playerText:choiceB,reply:replyB,replySpeaker:'Mực',replyAvatar:'🐈‍⬛'},
      {label:'Ghi lại bài học và chia sẻ với cộng đồng để mọi người cùng rút kinh nghiệm.',accepted:true,metric:'community',playerText:'Mình sẽ ghi lại bài học và chia sẻ với cộng đồng.',reply:'Một thay đổi nhỏ được chia sẻ đúng cách có thể giúp nhiều người cùng tiến bộ.',replySpeaker:'Mực',replyAvatar:'🐈‍⬛'},
      {label:bad,accepted:false,feedback}
    ]};
  }

  const chapters=[
    {title:'Nhìn nhận để sửa đổi',skill:'Tự nhận thức',act:1,scene:'Mảnh vườn đầu tiên đang mọc um tùm. Mực nhờ bạn quan sát, nhận ra điều chưa ổn và bắt đầu từ một việc nhỏ.',q:'Khi nhận ra cách làm của mình chưa hiệu quả, bạn nên làm gì?',a:['Che giấu để không ai biết', 'Đổ lỗi cho hoàn cảnh', 'Thừa nhận vấn đề, tìm nguyên nhân và sửa cách làm', 'Tiếp tục làm y như cũ'],c:2,why:'Tinh thần sửa đổi bắt đầu từ việc dám nhìn nhận thiếu sót và chủ động khắc phục.',task:'Trồng ít nhất một cây trong nông trại.',check:s=>(s.plots||[]).some(Boolean),taskText:'Có ít nhất một cây đang được trồng.',talks:[
      talk('Mực','🐈‍⬛','curious','Mảnh vườn này không tự nhiên trở nên um tùm. Trước khi sửa, ta cần nhìn đúng điều đang xảy ra.','Bạn sẽ bắt đầu thế nào?','Quan sát từng luống và ghi lại điều cần sửa.','Mình sẽ hỏi người làm vườn để hiểu thêm rồi cùng kiểm tra.','Làm đại một việc cho nhanh.','Quan sát có căn cứ giúp ta sửa đúng chỗ.','Có thêm góc nhìn sẽ giúp kế hoạch đầy đủ hơn.','Không nên làm vội khi chưa hiểu nguyên nhân.','Bác Năm','👨‍🌾'),
      talk('Bác Năm','👨‍🌾','warm','Bác từng ngại thừa nhận luống cây mình chăm chưa tốt. Nhưng giấu đi thì cây vẫn không khỏe hơn.','Khi phát hiện thiếu sót, bạn sẽ nói gì?','Cháu nhận phần mình làm chưa tốt và sẽ sửa từng bước.','Cháu muốn cùng bác tìm nguyên nhân để tránh lặp lại.','Chắc tại thời tiết, không phải lỗi của cháu.','Dám nhận trách nhiệm là bước đầu để tiến bộ.','Cùng tìm nguyên nhân giúp biến lời nhận lỗi thành hành động.','Đổ lỗi không giúp giải quyết vấn đề.') ]},
    {title:'Học đi đôi với hành',skill:'Vận dụng kiến thức',act:1,scene:'Trong thư viện, Mực mở một trang sách và nhắc rằng kiến thức chỉ có ích khi được vận dụng vào công việc thực tế.',q:'Cách học nào giúp kiến thức trở thành kỹ năng?',a:['Áp dụng vào thực hành, kiểm tra và rút kinh nghiệm', 'Chỉ học thuộc lòng', 'Chép bài mà không hiểu', 'Để người khác làm thay'],c:0,why:'Học tập cần gắn với thực hành và kết quả cụ thể.',task:'Trả lời đúng ít nhất 2 câu hỏi sách trong các hoạt động nông trại.',check:s=>(+s.actionQuizCorrect||0)>=2,taskText:'Đã trả lời đúng ít nhất 2 câu hỏi sách.',talks:[
      talk('Mực','🐈‍⬛','happy','Trong sách có nhiều điều đáng suy ngẫm. Nhưng chỉ đọc mà không áp dụng thì bài học vẫn nằm yên trên trang giấy.','Bạn sẽ học cách nào?','Đọc, thử áp dụng rồi xem kết quả.','Thực hành cùng người có kinh nghiệm và ghi lại điều học được.','Chỉ cần học thuộc câu chữ.','Thử nghiệm và kiểm tra giúp kiến thức trở thành kỹ năng.','Học cùng người khác giúp ta sửa sai nhanh hơn.','Học thuộc mà không hiểu chưa đủ để làm tốt.'),
      talk('Linh','👩‍🔬','curious','Trong phòng nghiên cứu, mỗi kết quả đều cần được kiểm tra. Một lần thử chưa thành công cũng cho ta thông tin.','Khi thử nghiệm chưa đạt, bạn nên làm gì?','Ghi lại kết quả và điều chỉnh cách làm.','Trao đổi với nhóm để tìm một cách thử khác.','Xóa kết quả vì nó không như mong muốn.','Ghi nhận cả kết quả chưa đạt là một phần của học tập.','Thảo luận giúp tìm thêm cách giải quyết.','Không nên xóa mất dữ liệu chỉ vì kết quả không như ý.','Mực','🐈‍⬛') ]},
    {title:'Lập kế hoạch trước khi làm',skill:'Quản lý thời gian',act:1,scene:'Mực đưa bạn một cuốn sổ nhiệm vụ. Nếu không sắp xếp thứ tự, khu vườn sẽ có việc bị bỏ quên.',q:'Một kế hoạch dễ thực hiện cần có gì?',a:['Chỉ cần mục tiêu chung', 'Càng nhiều việc càng tốt', 'Không cần xem lại tiến độ', 'Mục tiêu, bước làm, người phụ trách và thời hạn'],c:3,why:'Kế hoạch rõ ràng giúp xác định việc cần làm, thứ tự và thời gian hoàn thành.',task:'Thu hoạch ít nhất một cây.',check:s=>(+s.harvests||0)>=1,taskText:'Đã thu hoạch ít nhất một cây.',talks:[
      talk('Mực','🐈‍⬛','thinking','Khu vườn có nhiều việc: tưới cây, chăm pet, kiểm tra kho và giao hàng. Ta không thể làm tất cả cùng một lúc.','Bạn sẽ sắp xếp ra sao?','Chọn việc quan trọng, ghi thời hạn và kiểm tra tiến độ.','Chia việc theo khả năng rồi thống nhất thời điểm hoàn thành.','Làm việc nào dễ thấy trước thì làm, không cần ghi lại.','Kế hoạch có thứ tự giúp tránh bỏ sót việc quan trọng.','Phân công hợp lý giúp mọi người chủ động hơn.','Không có kế hoạch, công việc dễ bị chồng chéo.','Tí','🧑‍🌾'),
      talk('Tí','🧑‍🌾','energetic','Xe giao hàng chỉ có thể chở số lượng giới hạn. Nếu nhận quá nhiều đơn cùng lúc, chúng ta sẽ trễ hẹn.','Trước khi nhận thêm đơn, bạn cần kiểm tra gì?','Kiểm tra hàng tồn, thời gian và sức chở.','Hỏi người phụ trách kho để phối hợp chuẩn bị.','Nhận hết đơn rồi tính sau.','Kiểm tra nguồn lực giúp lời hứa phù hợp khả năng.','Phối hợp với kho giúp hạn chế nhầm lẫn.','Nhận quá nhiều khi chưa chuẩn bị dễ làm trễ việc.','Mực','🐈‍⬛') ]},
    {title:'Tinh thần trách nhiệm',skill:'Chủ động và cam kết',act:1,scene:'Bác Năm giao cho bạn một chuyến hàng. Mực nhắc: nhận việc là phải theo dõi đến khi hoàn thành.',q:'Khi gặp khó khăn có thể làm trễ nhiệm vụ, bạn nên làm gì?',a:['Im lặng đến hết hạn', 'Báo sớm, nêu khó khăn và đề xuất cách xử lý', 'Bỏ nhiệm vụ', 'Đổ lỗi cho đồng đội'],c:1,why:'Trách nhiệm thể hiện qua sự chủ động, trao đổi minh bạch và nỗ lực hoàn thành công việc.',task:'Giao ít nhất một chuyến nông sản hoặc hoàn thành một đơn NPC.',check:s=>deliveries(s)>=1,taskText:'Đã giao ít nhất một chuyến hàng.',talks:[
      talk('Tí','🧑‍🌾','worried','Một đơn hàng có thể bị trễ vì xe đang sửa. Khách vẫn đang chờ tin.','Bạn sẽ xử lý thế nào?','Báo khách sớm và đưa thời gian dự kiến mới.','Nhờ đồng đội hỗ trợ phương án giao thay thế.','Im lặng, hy vọng khách không để ý.','Thông báo kịp thời thể hiện sự tôn trọng người nhận.','Tìm phương án thay thế là cách chủ động giải quyết.','Im lặng khiến người khác không thể chuẩn bị.'),
      talk('Bác Năm','👨‍🌾','serious','Có trách nhiệm không có nghĩa là phải làm mọi thứ một mình. Quan trọng là không bỏ mặc công việc.','Khi không thể tự giải quyết, bạn nên làm gì?','Nêu rõ phần đã làm và nhờ hỗ trợ đúng người.','Đề xuất chia lại công việc để cả nhóm hoàn thành.','Tự ý bỏ nhiệm vụ.','Nhờ hỗ trợ đúng lúc không phải trốn tránh trách nhiệm.','Điều chỉnh phân công là cách bảo vệ mục tiêu chung.','Bỏ việc mà không báo là thiếu trách nhiệm.','Mực','🐈‍⬛') ]},
    {title:'Đoàn kết và phối hợp',skill:'Làm việc nhóm',act:2,scene:'Khu vườn có nhiều việc cùng lúc. Mực đề nghị bạn học cách phối hợp, quan tâm và hỗ trợ những người cùng làm.',q:'Cách phối hợp nào giúp nhóm làm việc tốt?',a:['Một người làm hết', 'Phân công rõ, hỗ trợ nhau và cùng chịu trách nhiệm', 'Không chia sẻ tiến độ', 'Mỗi người tự làm, không trao đổi'],c:1,why:'Đoàn kết cần có phân công, phối hợp và trách nhiệm chung.',task:'Chăm sóc pet để tăng mức thân thiết.',check:s=>+(s.pet&&s.pet.bond||0)>0,taskText:'Pet có ít nhất 1 điểm thân thiết.',talks:[
      talk('Bác Năm','👨‍🌾','warm','Bác chăm đất, Linh nghiên cứu giống, còn Tí lo giao hàng. Mỗi người có phần việc khác nhau.','Làm sao để cả nhóm phối hợp tốt?','Thống nhất mục tiêu và chia việc rõ ràng.','Thường xuyên cập nhật để người khác hỗ trợ khi cần.','Ai làm xong phần mình thì không cần quan tâm việc chung.','Phân công rõ giúp tránh bỏ sót hoặc làm trùng việc.','Chia sẻ tiến độ giúp nhóm xử lý vấn đề sớm.','Mục tiêu chung cần sự phối hợp chứ không chỉ các phần riêng lẻ.','Linh','👩‍🔬'),
      talk('Linh','👩‍🔬','happy','Một thành viên mới chưa quen việc. Nếu được hướng dẫn, bạn ấy có thể đóng góp tốt hơn.','Bạn sẽ hỗ trợ thế nào?','Chỉ dẫn từng bước và cùng kiểm tra kết quả.','Hỏi bạn ấy cần hỗ trợ gì rồi cùng làm.','Chê trách vì làm chậm cả nhóm.','Hướng dẫn cụ thể giúp người mới tự tin hơn.','Lắng nghe nhu cầu giúp hỗ trợ đúng lúc.','Chê trách không giúp người khác học được cách làm.'),
    ]},
    {title:'Lắng nghe và góp ý',skill:'Phản hồi xây dựng',act:2,scene:'Linh trong phòng nghiên cứu có một ý tưởng khác bạn. Mực khuyên nên lắng nghe trước khi kết luận.',q:'Khi góp ý cho bạn học, cách nào phù hợp?',a:['Chỉ trích cá nhân', 'Nói bóng gió', 'Không nói dù lỗi ảnh hưởng cả nhóm', 'Nêu việc cụ thể, có căn cứ và đề xuất hướng sửa'],c:3,why:'Góp ý cần chân thành, cụ thể, có căn cứ và hướng đến cải thiện công việc.',task:'Khám phá ít nhất một giống cây trong phòng thí nghiệm.',check:s=>(s.collections&&s.collections.crops||[]).length>0,taskText:'Đã mở khóa ít nhất một giống cây.',talks:[
      talk('Linh','👩‍🔬','curious','Bản thử nghiệm của mình có một điểm chưa ổn. Bạn phát hiện biểu đồ thiếu chú thích.','Bạn sẽ góp ý thế nào?','Chỉ rõ biểu đồ nào thiếu chú thích và đề nghị bổ sung.','Hỏi người thực hiện có muốn cùng rà lại báo cáo không.','Nói rằng người làm báo cáo quá cẩu thả.','Góp ý cụ thể giúp người nghe biết cần sửa gì.','Cùng rà soát khiến phản hồi trở thành hợp tác.','Nhận xét cá nhân dễ làm người khác phòng thủ.'),
      talk('Mực','🐈‍⬛','serious','Góp ý cũng cần đúng lúc và tôn trọng. Ta không nên biến khác biệt thành tranh cãi.','Nếu người nghe chưa đồng ý, bạn nên làm gì?','Đưa ra căn cứ và lắng nghe phản hồi.','Tạm dừng, hẹn trao đổi khi cả hai bình tĩnh.','Cố nói cho đến khi người kia phải nhận sai.','Căn cứ giúp cuộc trao đổi tập trung vào vấn đề.','Biết tạm dừng cũng là một kỹ năng giao tiếp.','Mục tiêu là cải thiện công việc, không phải thắng tranh luận.') ]},
    {title:'Nói và viết rõ ràng',skill:'Giao tiếp thiết thực',act:2,scene:'Mực nhờ bạn viết bảng thông báo cho khu phố. Một thông tin rõ ràng giúp mọi người hiểu và thực hiện đúng.',q:'Một thông báo công việc tốt nên như thế nào?',a:['Rõ ý, đúng trọng tâm và có thông tin cần thiết', 'Dài và có nhiều câu ngoài lề', 'Dùng từ khó để tạo ấn tượng', 'Không cần kiểm tra nội dung'],c:0,why:'Nội dung rõ ràng, thiết thực giúp người đọc hiểu đúng và hành động thuận lợi.',task:'Giao ít nhất hai chuyến hàng.',check:s=>deliveries(s)>=2,taskText:'Tổng số chuyến giao hàng đạt ít nhất 2.',talks:[
      talk('Tí','🧑‍🌾','energetic','Bảng thông báo giao hàng cần nói rõ địa điểm, số lượng và thời hạn.','Bạn sẽ viết thông báo thế nào?','Dùng câu ngắn, nêu đủ thông tin cần thiết.','Thêm biểu tượng và chia mục để dễ đọc.','Viết thật dài để trông chuyên nghiệp.','Thông tin ngắn gọn giúp người đọc nắm việc nhanh.','Cách trình bày trực quan cũng giúp giảm nhầm lẫn.','Dài dòng không đồng nghĩa với rõ ràng.'),
      talk('Mực','🐈‍⬛','thinking','Trước khi gửi thông báo, ta cần kiểm tra lại tên, số lượng và thời gian.','Bước cuối cùng nên là gì?','Đọc lại và đối chiếu thông tin với nguồn gốc.','Nhờ một người khác kiểm tra chéo.','Gửi ngay mà không cần xem lại.','Đối chiếu giúp phát hiện lỗi thông tin.','Kiểm tra chéo tạo thêm một lớp bảo đảm.','Sai thông tin có thể gây rắc rối cho cả nhóm.') ]},
    {title:'Kiểm tra và rút kinh nghiệm',skill:'Tự đánh giá',act:2,scene:'Một luống cây phát triển chậm. Mực cùng bạn kiểm tra điều kiện chăm sóc để tìm cách cải thiện.',q:'Sau khi hoàn thành một công việc, nên làm gì?',a:['Không cần xem lại', 'Chỉ ghi nhận thành tích', 'Đánh giá kết quả, tìm điểm tốt và điểm cần sửa', 'Xóa các ghi chú'],c:2,why:'Kiểm tra giúp nhận ra hạn chế và giữ lại kinh nghiệm hữu ích.',task:'Khám phá một loài côn trùng trong khu vườn.',check:()=>bugs().length>0,taskText:'Đã ghi nhận ít nhất một loài côn trùng trong Index.',talks:[
      talk('Mực','🐈‍⬛','thinking','Luống cây này phát triển chậm hơn dự kiến. Ta cần xem lại điều kiện và cách chăm sóc.','Bạn sẽ kiểm tra điều gì trước?','Đối chiếu dữ liệu tưới, ánh sáng và tình trạng đất.','Hỏi người chăm luống ghi lại thay đổi gần đây.','Kết luận ngay rằng hạt giống bị lỗi.','Dữ liệu giúp tìm nguyên nhân thay vì đoán mò.','Nhật ký chăm sóc giúp lần theo các thay đổi.','Chưa đủ thông tin thì chưa nên kết luận.'),
      talk('Bác Năm','👨‍🌾','warm','Sau mỗi vụ, bác thường ghi điều gì hiệu quả và điều gì cần thay đổi.','Bạn sẽ giữ lại kinh nghiệm bằng cách nào?','Ghi kết quả và bài học vào sổ.','Chia sẻ điều rút ra với người cùng làm.','Chỉ nhớ trong đầu, không cần ghi.','Ghi chép giúp kinh nghiệm không bị thất lạc.','Chia sẻ giúp cả nhóm cùng tiến bộ.','Kinh nghiệm sẽ khó dùng lại nếu không được lưu giữ.') ]},
    {title:'Tôn trọng tập thể và góc nhìn khác',skill:'Tư duy khách quan',act:2,scene:'Trong cuộc họp làng, mỗi người đưa ra một cách giải quyết. Mực nhắc bạn xem xét ý kiến bằng lý lẽ và thực tế.',q:'Khi nghe ý kiến khác với mình, nên làm gì?',a:['Bác bỏ ngay', 'Chỉ nghe người thân thiết', 'Tranh luận để thắng', 'Lắng nghe, kiểm chứng và chọn phương án có căn cứ'],c:3,why:'Tư duy khách quan đòi hỏi lắng nghe và xem xét vấn đề trên căn cứ thực tế.',task:'Tích lũy ít nhất 30 điểm nghiên cứu.',check:s=>(+s.researchPoints||0)>=30,taskText:'Điểm nghiên cứu đạt từ 30 trở lên.',talks:[
      talk('Linh','👩‍🔬','curious','Trong cuộc họp có hai phương án khác nhau. Mỗi người đều có lý do riêng.','Bạn nên làm gì trước khi quyết định?','So sánh ưu, nhược điểm và bằng chứng của từng phương án.','Mời cả hai bên trình bày rồi thống nhất tiêu chí.','Chọn ý kiến của người thân với mình.','So sánh trên căn cứ giúp quyết định công bằng hơn.','Thống nhất tiêu chí giúp cuộc thảo luận rõ ràng.','Không nên chọn ý kiến chỉ vì người nói là ai.'),
      talk('Mực','🐈‍⬛','serious','Có lúc kết quả thực tế khác với điều ta mong muốn. Người khách quan cần sẵn sàng thay đổi ý kiến.','Nếu bằng chứng mới cho thấy mình chưa đúng, bạn sẽ làm gì?','Cập nhật kết luận và giải thích vì sao thay đổi.','Cảm ơn người đưa ra thông tin mới và kiểm tra thêm.','Giữ nguyên ý kiến để khỏi mất mặt.','Thay đổi khi có căn cứ là biểu hiện của học hỏi.','Thái độ cầu thị giúp cuộc trao đổi tiến bộ.','Giữ thể diện không quan trọng hơn sự thật.') ]},
    {title:'Biến tri thức thành hành động',skill:'Cải tiến liên tục',act:3,scene:'Cây Tri Thức dần phát sáng. Mực nói rằng hành trình chỉ có ý nghĩa khi những điều đã học trở thành thói quen làm việc tốt.',q:'Điều quan trọng nhất sau khi học được một bài học là gì?',a:['Chỉ ghi nhớ câu trả lời', 'Áp dụng, theo dõi kết quả và tiếp tục điều chỉnh', 'Chia sẻ khẩu hiệu', 'Chờ người khác thay đổi trước'],c:1,why:'Tri thức có giá trị khi được biến thành hành động cụ thể và cải tiến liên tục.',task:'Có ít nhất 3 lần thu hoạch và 2 chuyến giao hàng.',check:s=>(+s.harvests||0)>=3&&deliveries(s)>=2,taskText:'Đạt 3 lượt thu hoạch và 2 chuyến giao hàng.',talks:[
      talk('Mực','🐈‍⬛','hopeful','Bạn đã học được nhiều điều. Nhưng làm sao để những điều đó không chỉ dừng ở lời nói?','Bạn sẽ bắt đầu duy trì thay đổi thế nào?','Chọn một việc cụ thể, thực hiện đều và tự đánh giá.','Rủ một người bạn cùng theo dõi tiến độ.','Chờ người khác thay đổi trước.','Thói quen nhỏ được duy trì sẽ tạo ra tiến bộ.','Có người đồng hành giúp duy trì động lực.','Sự thay đổi của mình không cần đợi người khác.'),
      talk('Linh','👩‍🔬','happy','Cây Tri Thức sắp nở hoa. Mỗi người trong làng đã góp một phần công sức.','Thông điệp nào bạn muốn gửi đến mọi người?','Tri thức cần đi cùng hành động và trách nhiệm.','Mỗi người sửa một việc nhỏ, cả cộng đồng sẽ tiến lên.','Chỉ cần hoàn thành nhiệm vụ để nhận thưởng.','Hành động biến kiến thức thành giá trị thực tế.','Sự thay đổi tích cực lan tỏa khi mọi người cùng tham gia.','Phần thưởng không phải mục đích cuối cùng.','Mực','🐈‍⬛') ]},

   
    {title:'Bức thư bí ẩn',skill:'Quan sát và xác minh thông tin',act:3,scene:'Mực tìm thấy một phong thư cũ trước thư viện. Tấm bản đồ bên trong đánh dấu Nhà kính số 7, nơi đã đóng cửa nhiều năm.',q:'Khi nhận được thông tin chưa rõ nguồn gốc, bạn nên làm gì?',a:['Chia sẻ ngay cho mọi người', 'Tin vì thư có con dấu cũ', 'Kiểm tra nguồn, đối chiếu dữ kiện và hỏi người có trách nhiệm', 'Tự thêm chi tiết còn thiếu'],c:2,why:'Thông tin cần được kiểm chứng trước khi sử dụng hoặc chia sẻ.',task:'Đã khám phá ít nhất một giống cây hoặc trả lời đúng một câu hỏi sách.',check:s=>(s.collections&&s.collections.crops||[]).length>0||(+s.actionQuizCorrect||0)>=1,taskText:'Có ít nhất một giống cây được khám phá hoặc một câu trả lời sách đúng.',talks:[
      talk('Mực','🐈‍⬛','curious','Bức thư không ghi tên người gửi. Bản đồ có thể quan trọng, nhưng ta chưa biết nó có đáng tin không.','Bạn sẽ kiểm tra bằng cách nào?','Đối chiếu con dấu, ngày tháng và hồ sơ thư viện.','Hỏi bác Tư xem có nhớ dự án cũ không.','Tự đoán người gửi rồi đi tìm ngay.','Đối chiếu tài liệu giúp xác minh nguồn.','Nhân chứng có thể cung cấp manh mối cần kiểm tra chéo.','Không nên biến phỏng đoán thành sự thật.','Bác Tư','👨‍🌾'),
      talk('Bác Tư','👨‍🌾','serious','Bác nhớ từng có một dự án ở Nhà kính số 7, nhưng ký ức của bác có thể không đầy đủ.','Bạn sẽ ghi lời kể thế nào?','Ghi rõ đây là lời kể và tìm tài liệu xác nhận.','Hỏi thêm người khác để so sánh các mốc thời gian.','Ghi lời kể thành sự thật đã được xác nhận.','Phân biệt lời kể và chứng cứ là rất quan trọng.','Nhiều nguồn độc lập giúp kiểm tra độ tin cậy.','Không nên kết luận chỉ từ một lời kể.') ]},
    {title:'Cánh cửa niêm phong',skill:'Tôn trọng quy định và an toàn',act:3,scene:'Lối vào nhà kính đã được niêm phong. Mực nhắc rằng tò mò không phải lý do để tự ý vượt qua khu vực hạn chế.',q:'Khi gặp khu vực được niêm phong, lựa chọn phù hợp là gì?',a:['Nhờ người có thẩm quyền xác nhận và cho phép tiếp cận', 'Tự ý phá niêm phong', 'Đi vòng vào bằng lối khác', 'Nhờ bạn mở hộ'],c:0,why:'Tôn trọng quy định và chỉ tiếp cận khi được người có trách nhiệm cho phép giúp bảo đảm an toàn.',task:'Tích lũy ít nhất 5 điểm nghiên cứu.',check:s=>(+s.researchPoints||0)>=5,taskText:'Điểm nghiên cứu đạt ít nhất 5.',talks:[
      talk('Mực','🐈‍⬛','serious','Cánh cửa có dấu niêm phong. Ta không biết bên trong có nguy hiểm hay không.','Bạn sẽ làm gì trước?','Dừng lại, ghi nhận hiện trạng và liên hệ người phụ trách.','Hỏi bác Tư về quy trình xin phép tiếp cận.','Tự tìm cách mở cửa để xem bên trong.','Giữ nguyên hiện trường giúp tránh rủi ro và mất dấu vết.','Hỏi người phụ trách là cách đúng quy trình.','Không nên tự ý đi vào khu vực hạn chế.','Bác Tư','👨‍🌾'),
      talk('Bác Tư','👨‍🌾','warm','Bác có thể giúp liên hệ người quản lý, nhưng cần ghi rõ mục đích điều tra.','Bạn sẽ trình bày mục đích thế nào?','Nêu câu hỏi cần tìm hiểu và phạm vi cần tiếp cận.','Đề nghị có người phụ trách đi cùng.','Nói rằng mình chỉ tò mò nên cần vào ngay.','Mục đích rõ ràng giúp người quản lý đánh giá yêu cầu.','Có người phụ trách giúp bảo đảm an toàn.','Tò mò không thay thế được sự cho phép.','Mực','🐈‍⬛') ]},
    {title:'Những trang hồ sơ mất tích',skill:'Sắp xếp và bảo toàn tài liệu',act:3,scene:'Trong kho lưu trữ, nhiều trang hồ sơ nằm lẫn lộn. Một số trang đã rách và không còn thứ tự.',q:'Cách khôi phục hồ sơ phù hợp nhất là gì?',a:['Phân loại theo ngày, nguồn và chủ đề; giữ nguyên bản gốc', 'Sắp xếp theo cảm tính', 'Tự viết lại phần bị thiếu', 'Bỏ những trang khó đọc'],c:0,why:'Phân loại có tiêu chí và bảo toàn bản gốc giúp tài liệu có thể kiểm tra lại.',task:'Trả lời đúng ít nhất 2 câu hỏi sách.',check:s=>(+s.actionQuizCorrect||0)>=2,taskText:'Đã trả lời đúng ít nhất 2 câu hỏi sách.',talks:[
      talk('Linh','👩‍🔬','thinking','Các trang hồ sơ có ngày tháng và mã lưu trữ khác nhau. Nếu trộn lẫn, ta có thể hiểu sai trình tự.','Bạn sẽ sắp xếp thế nào?','Phân loại theo mã, ngày và nguồn trước khi ghép.','Chụp bản lưu rồi cùng một người khác kiểm tra.','Ghép theo cảm giác để câu chuyện liền mạch.','Tiêu chí rõ giúp việc khôi phục có thể kiểm chứng.','Lưu bản sao giúp giảm nguy cơ mất tài liệu.','Không nên tự tạo thứ tự khi chưa có căn cứ.'),
      talk('Mực','🐈‍⬛','curious','Có một trang bị mất góc. Ta không nên tự điền phần mình không biết.','Bạn sẽ ghi chú ra sao?','Đánh dấu phần khuyết và ghi rõ chưa xác minh.','Tìm bản lưu ở nguồn khác để đối chiếu.','Tự đoán nội dung rồi viết vào bản gốc.','Ghi rõ chỗ chưa biết giúp người đọc không nhầm lẫn.','Đối chiếu nguồn khác có thể tìm ra bản đầy đủ.','Không được biến suy đoán thành tài liệu gốc.') ]},
    {title:'Dấu chân trong mưa',skill:'Ghi nhận hiện trường khách quan',act:3,scene:'Sau trận mưa, gần nhà kính xuất hiện những dấu chân mờ. Mực đề nghị ghi nhận mà không làm xáo trộn hiện trường.',q:'Khi quan sát dấu vết chưa rõ, nên làm gì?',a:['Tự kết luận ngay ai đã đi qua', 'Làm sạch khu vực', 'Ghi lại vị trí, thời gian và đặc điểm nhìn thấy; không suy đoán danh tính', 'Đăng ảnh kèm lời buộc tội'],c:2,why:'Quan sát khách quan cần tách điều nhìn thấy khỏi suy đoán về nguyên nhân hoặc người liên quan.',task:'Khám phá ít nhất một loài côn trùng trong Index.',check:()=>bugs().length>0,taskText:'Đã ghi nhận ít nhất một loài côn trùng.',talks:[
      talk('Mực','🐈‍⬛','curious','Mưa làm dấu vết nhòe đi. Ta chỉ có thể ghi những gì thật sự quan sát được.','Bạn sẽ ghi nhận điều gì?','Vị trí, thời điểm và hình dạng còn nhìn thấy.','Chụp ảnh từ vị trí an toàn và ghi điều kiện thời tiết.','Đoán người để lại dấu chân dựa trên kích thước.','Ghi dữ kiện cụ thể giúp người khác kiểm tra lại.','Ảnh kèm bối cảnh giúp giữ thông tin hiện trường.','Kích thước dấu chân không đủ để xác định một người.'),
      talk('Bác Tư','👨‍🌾','serious','Bác muốn biết ai đã đến, nhưng ta không nên nêu tên khi chưa có chứng cứ.','Bạn sẽ báo cáo thế nào?','Nêu dấu vết đã ghi nhận và nói rõ điều chưa biết.','Đề nghị người có trách nhiệm tiếp tục kiểm tra.','Đăng lời buộc tội lên bảng tin làng.','Báo cáo trung thực giúp tránh gây hại cho người vô can.','Chuyển việc xác minh cho người có trách nhiệm là phù hợp.','Không nên lan truyền cáo buộc chưa được xác minh.','Mực','🐈‍⬛') ]},
    {title:'Mẫu vật được niêm phong',skill:'Giám định có trách nhiệm',act:4,scene:'Một hộp mẫu vật được lưu giữ trong tủ an toàn. Người chơi chỉ được quan sát dữ liệu và nhờ nhân viên chuyên môn phân tích.',q:'Khi gặp mẫu vật chưa rõ thành phần, cần làm gì?',a:['Tự mở và thử bằng giác quan', 'Giữ nguyên niêm phong, ghi mã mẫu và chuyển người chuyên môn', 'Mang về nhà quan sát', 'Chia mẫu cho bạn bè'],c:1,why:'Mẫu chưa rõ thành phần cần được xử lý bởi người có chuyên môn theo quy trình an toàn.',task:'Nhà kính đã được xây hoặc đã mở khóa ít nhất một giống nghiên cứu.',check:()=>{const e=expansion();return !!(e.greenhouse&&e.greenhouse.built)||(game().unlockedResearchSeeds||[]).length>0},taskText:'Nhà kính đã hoàn thành hoặc có giống nghiên cứu được mở khóa.',talks:[
      talk('Linh','👩‍🔬','serious','Hộp mẫu có mã nhận diện nhưng chưa có kết quả giám định. Chúng ta không biết bên trong chứa gì.','Bạn sẽ xử lý hộp mẫu thế nào?','Giữ nguyên niêm phong và ghi lại mã mẫu.','Báo nhân viên chuyên môn để kiểm tra theo quy trình.','Mở hộp để tự xem thử.','Giữ nguyên mẫu tránh phơi nhiễm và bảo toàn chứng cứ.','Người chuyên môn có thiết bị và quy trình phù hợp.','Không tự ý mở hoặc tiếp xúc mẫu chưa rõ.'),
      talk('Mực','🐈‍⬛','thinking','Kết quả máy phân tích sẽ cần được giải thích bởi người có chuyên môn.','Bạn sẽ trình bày kết quả ra sao?','Ghi rõ phương pháp, giới hạn và người xác nhận.','Đính kèm mã mẫu để có thể truy xuất.','Chỉ công bố kết luận mà không ghi nguồn.','Nêu giới hạn giúp người đọc hiểu đúng kết quả.','Mã mẫu giúp truy xuất tài liệu chính xác.','Kết luận không có nguồn sẽ khó kiểm chứng.','Linh','👩‍🔬') ]},
    {title:'Nhật ký phòng nghiên cứu',skill:'Đọc hiểu và đối chiếu dữ liệu',act:4,scene:'Nhật ký nghiên cứu có nhiều ghi chú theo ngày. Một số ý kiến cá nhân được viết xen với kết quả quan sát.',q:'Khi đọc nhật ký nghiên cứu, điều gì cần được phân biệt?',a:['Chỉ đọc dòng kết luận', 'Bỏ qua ngày tháng', 'Coi mọi ghi chú là kết quả đã xác minh', 'Sự kiện được ghi nhận và ý kiến cá nhân'],c:3,why:'Tách dữ kiện, nhận xét và kết luận giúp đánh giá tài liệu chính xác hơn.',task:'Thu hoạch ít nhất 2 cây.',check:s=>(+s.harvests||0)>=2,taskText:'Đã thu hoạch ít nhất 2 cây.',talks:[
      talk('Linh','👩‍🔬','curious','Trong nhật ký có dòng “mẫu này có vẻ bất thường” và một bảng đo. Hai loại thông tin này không giống nhau.','Bạn sẽ phân loại thế nào?','Bảng đo là dữ liệu; câu nhận xét là ý kiến cần kiểm tra.','Ghi ngày tháng và người ghi cho cả hai phần.','Coi nhận xét là kết luận chắc chắn.','Phân biệt dữ liệu và nhận định giúp tránh hiểu sai.','Nguồn và thời điểm giúp đánh giá độ tin cậy.','Một nhận xét chưa phải kết luận khoa học.'),
      talk('Mực','🐈‍⬛','thinking','Một trang nhật ký có số liệu nhưng thiếu đơn vị đo. Ta cần bổ sung từ nguồn gốc chứ không đoán.','Bạn sẽ làm gì?','Tìm phiếu đo gốc hoặc hỏi người ghi chép.','Đánh dấu thông tin còn thiếu trong bản tổng hợp.','Tự thêm đơn vị mà mình cho là hợp lý.','Tìm nguồn gốc giúp khôi phục dữ liệu đúng.','Đánh dấu phần thiếu giúp người đọc biết giới hạn.','Không nên tự điền dữ liệu chưa rõ.') ]},
    {title:'Những con số bất thường',skill:'Tư duy dữ liệu',act:4,scene:'Một báo cáo cho thấy chỉ số môi trường thay đổi mạnh. Linh cần bạn xác định liệu thay đổi đó có phải xu hướng thật hay không.',q:'Muốn đánh giá một con số bất thường, nên làm gì?',a:['Chỉ nhìn một con số', 'So sánh với dữ liệu nền, thời gian và điều kiện đo', 'Bỏ qua đơn vị', 'Kết luận ngay có vi phạm'],c:1,why:'Số liệu cần bối cảnh, đơn vị, phương pháp đo và dữ liệu so sánh.',task:'Tích lũy ít nhất 30 điểm nghiên cứu.',check:s=>(+s.researchPoints||0)>=30,taskText:'Điểm nghiên cứu đạt ít nhất 30.',talks:[
      talk('Linh','👩‍🔬','serious','Một con số tăng đột ngột chưa nói lên toàn bộ câu chuyện. Có thể thiết bị, thời tiết hoặc cách đo đã thay đổi.','Bạn sẽ kiểm tra điều gì trước?','Đơn vị đo, thời điểm và thiết bị sử dụng.','So sánh với dữ liệu các ngày trước trong cùng điều kiện.','Chỉ chọn con số lớn nhất để kết luận.','Kiểm tra phương pháp đo giúp loại trừ sai số.','Dữ liệu nền giúp nhận biết xu hướng.','Một điểm dữ liệu riêng lẻ chưa đủ để kết luận.'),
      talk('Mực','🐈‍⬛','curious','Nếu hai báo cáo khác nhau, ta cần tìm lý do thay vì chọn báo cáo mình thích.','Bạn sẽ giải quyết sự khác biệt thế nào?','Đối chiếu nguồn và phương pháp của cả hai báo cáo.','Ghi rõ điểm chưa thống nhất để kiểm tra thêm.','Bỏ báo cáo có kết quả mình không thích.','Đối chiếu giúp tìm nguyên nhân khác biệt.','Ghi nhận bất đồng làm báo cáo minh bạch hơn.','Không nên chỉ chọn dữ liệu thuận với ý kiến của mình.','Bác Tư','👨‍🌾') ]},
    {title:'Đường dây bí mật',skill:'Lập sơ đồ quan hệ có căn cứ',act:4,scene:'Các hồ sơ nhắc đến nhiều nhân vật và đơn vị khác nhau. Người chơi phải tìm hiểu mối liên hệ mà không vội quy kết.',q:'Khi lập sơ đồ quan hệ từ hồ sơ, cần làm gì?',a:['Chỉ nối các mối liên hệ có tài liệu xác nhận và ghi mức độ chắc chắn', 'Nối mọi cái tên xuất hiện với nhau', 'Dùng tin đồn để bổ sung', 'Công bố danh tính người chưa được xác minh'],c:0,why:'Sơ đồ điều tra phải dựa trên chứng cứ, ghi rõ nguồn và không biến liên hệ thành cáo buộc.',task:'Hoàn thành ít nhất 2 chuyến giao hàng.',check:s=>deliveries(s)>=2,taskText:'Tổng số chuyến giao hàng đạt ít nhất 2.',talks:[
      talk('Mực','🐈‍⬛','serious','Một cái tên xuất hiện trong hai tài liệu. Điều đó chưa chứng minh người ấy có liên quan đến mọi sự việc.','Bạn sẽ ghi mối liên hệ thế nào?','Chỉ ghi điều tài liệu xác nhận và đính kèm nguồn.','Đánh dấu mối liên hệ là giả thuyết cần kiểm tra.','Kết luận ngay người đó chịu trách nhiệm.','Gắn nguồn giúp người khác kiểm tra lại.','Phân biệt giả thuyết và sự kiện là rất quan trọng.','Không được quy kết khi chưa đủ chứng cứ.'),
      talk('Bác Tư','👨‍🌾','worried','Người dân đang bàn tán nhiều điều. Bác muốn báo cáo trung thực để tránh làm tổn thương người vô can.','Bạn sẽ trình bày với cộng đồng thế nào?','Chia sẻ kết quả đã xác minh và nêu rõ điều chưa biết.','Để người có thẩm quyền tiếp tục xử lý phần nhạy cảm.','Đăng mọi tên tuổi lên bảng tin.','Minh bạch có trách nhiệm giúp cộng đồng hiểu đúng.','Thông tin nhạy cảm cần được xử lý đúng vai trò.','Không nên công khai danh tính dựa trên đồn đoán.','Mực','🐈‍⬛') ]},
    {title:'Lời kể của Minh',skill:'Đồng cảm và lắng nghe',act:5,scene:'Minh, một học sinh trong làng, kể rằng bạn ấy đang gặp nhiều áp lực. Người chơi cần lắng nghe mà không phán xét.',q:'Khi một người bạn chia sẻ khó khăn, cách phản hồi phù hợp là gì?',a:['Ngắt lời và đưa ra phán xét', 'Kể chuyện của mình để át lời bạn', 'Lắng nghe bình tĩnh, hỏi bạn cần hỗ trợ gì và khuyến khích tìm người đáng tin cậy', 'Hứa giữ bí mật trong mọi tình huống'],c:2,why:'Lắng nghe tôn trọng và kết nối với người hỗ trợ đáng tin cậy giúp người gặp khó khăn không phải đối mặt một mình.',task:'Tăng mức thân thiết của pet lên ít nhất 5.',check:s=>+(s.pet&&s.pet.bond||0)>=5,taskText:'Mức thân thiết của pet đạt ít nhất 5.',talks:[
      talk('Minh','🧑','worried','Dạo này mình thấy áp lực và không biết nên bắt đầu kể từ đâu.','Bạn sẽ nói gì với Minh?','Mình sẵn sàng lắng nghe. Bạn muốn kể điều gì trước?','Bạn có muốn cùng tìm một người lớn đáng tin để hỗ trợ không?','Đừng nghĩ nhiều, chuyện đó nhỏ thôi.','Lắng nghe không phán xét giúp người bạn cảm thấy được tôn trọng.','Kết nối hỗ trợ đáng tin cậy là một bước tích cực.','Không nên xem nhẹ cảm xúc hay khó khăn của người khác.','Mực','🐈‍⬛'),
      talk('Mực','🐈‍⬛','gentle','Minh lo rằng nếu chia sẻ, bạn ấy sẽ bị đánh giá. Ta cần tôn trọng nhưng không hứa giữ bí mật nếu có nguy cơ mất an toàn.','Bạn sẽ làm gì tiếp theo?','Khuyến khích Minh nói với người lớn đáng tin cậy.','Đề nghị cùng Minh tìm giáo viên hoặc người thân để trò chuyện.','Hứa sẽ không nói với bất kỳ ai dù có nguy hiểm.','Người đáng tin cậy có thể giúp Minh tìm hỗ trợ phù hợp.','Đồng hành cùng bạn giúp việc tìm trợ giúp bớt khó khăn.','An toàn quan trọng hơn lời hứa giữ bí mật tuyệt đối.','Bác Tư','👨‍🌾') ]},
    {title:'Ánh sáng Nhà kính số 7',skill:'Tổng hợp và hành động có trách nhiệm',act:5,scene:'Những hồ sơ đã được kiểm tra. Cộng đồng cùng lập kế hoạch phục hồi Nhà kính số 7 và trả lại khu vườn cho mọi người.',q:'Một báo cáo kết thúc tốt cần có những gì?',a:['Chỉ nêu điều thuận lợi', 'Nêu tên người bị nghi ngờ dù chưa xác minh', 'Chỉ dùng khẩu hiệu', 'Chứng cứ, giới hạn, bài học và kế hoạch hành động cụ thể'],c:3,why:'Một báo cáo có trách nhiệm trình bày căn cứ, giới hạn và giải pháp thực tế.',task:'Hoàn thành nhà kính, có ít nhất 5 lần thu hoạch và 2 chuyến giao hàng.',check:s=>{const e=expansion();return !!(e.greenhouse&&e.greenhouse.built)&&(+s.harvests||0)>=5&&deliveries(s)>=2},taskText:'Nhà kính hoàn thành, thu hoạch ít nhất 5 lần và giao ít nhất 2 chuyến.',talks:[
      talk('Linh','👩‍🔬','hopeful','Chúng ta đã có hồ sơ, lời kể và dữ liệu. Bây giờ cần trình bày điều đã xác minh cùng những giới hạn còn lại.','Bạn sẽ tổ chức báo cáo thế nào?','Trình bày theo chứng cứ, kết luận và phần còn cần kiểm tra.','Mời các nhóm cùng rà soát trước khi công bố.','Chỉ trình bày kết luận mình thích nhất.','Bố cục rõ giúp người nghe theo dõi lập luận.','Rà soát chung giúp phát hiện thiếu sót.','Báo cáo cần trung thực, kể cả khi còn điều chưa rõ.'),
      talk('Mực','🐈‍⬛','happy','Nhà kính đã sáng đèn trở lại. Điều quan trọng không phải tìm một người để đổ lỗi, mà là học cách ngăn vấn đề tái diễn.','Bạn muốn để lại lời nhắn nào cho cộng đồng?','Cùng chịu trách nhiệm, kiểm tra định kỳ và tiếp tục học hỏi.','Chia sẻ bài học để người khác tránh lặp lại sai lầm.','Xem như mọi chuyện đã xong và không cần nhìn lại.','Kế hoạch duy trì giúp thành quả được bảo vệ lâu dài.','Lan tỏa bài học giúp cộng đồng cùng tiến bộ.','Muốn thay đổi bền vững cần tiếp tục theo dõi và cải tiến.','Minh','🧑') ]}
  ];

  const dialogueAdditions = [["Ta không cần sửa mọi thứ cùng lúc; hãy bắt đầu từ điều có thể quan sát và kiểm tra.", "Bác sẽ cùng cháu đi từng luống, nhưng cháu hãy tự ghi lại điều mình phát hiện."], ["Một trang sách chỉ thật sự có ích khi người đọc đem điều học được vào công việc.", "Mình sẽ ghi cả lần thử chưa đạt, vì dữ liệu đó giúp lần sau tốt hơn."], ["Ưu tiên không phải làm nhiều nhất, mà là chọn đúng việc cần làm trước.", "Kho còn giới hạn sức chở; mình nên chốt đơn theo năng lực thực tế."], ["Người nhận hàng cần một lời báo sớm và trung thực hơn một lời hứa thiếu chắc chắn.", "Bác có thể hỗ trợ, nhưng cháu hãy nói rõ phần việc nào đã hoàn thành."], ["Mỗi người giữ một phần việc, nhưng kết quả của khu vườn là trách nhiệm chung.", "Mình sẽ ghi rõ ai phụ trách, ai kiểm tra và lúc nào cả nhóm cùng rà soát."], ["Góp ý đúng cách không làm người nghe kém đi; nó giúp công việc tốt hơn.", "Ta hãy nói về điểm cần sửa của bản báo cáo, không gắn lỗi đó với giá trị của người viết."], ["Một thông báo rõ ràng giúp người nhận biết phải làm gì, ở đâu và khi nào.", "Mình sẽ đọc lại nội dung như người nhận lần đầu để xem có chỗ nào dễ hiểu nhầm không."], ["Rà soát không phải để tìm người đáng trách, mà để hiểu điều gì nên giữ và điều gì cần đổi.", "Mình sẽ ghi lại bài học ngay khi công việc còn mới, tránh quên mất nguyên nhân."], ["Ý kiến khác biệt có thể giúp ta thấy phần mình chưa nhìn ra.", "Mình sẽ hỏi thêm căn cứ của ý kiến đó trước khi cùng chọn phương án."], ["Một thay đổi nhỏ được duy trì đều đặn thường có ích hơn một lời hứa lớn rồi bỏ dở.", "Mình sẽ theo dõi kết quả sau khi áp dụng để biết điều chỉnh có thật sự hiệu quả không."], ["Một bức thư cũ chưa chắc đã phản ánh đầy đủ sự việc; nguồn gửi cần được xác minh.", "Bác sẽ đối chiếu dấu mốc trên thư với sổ lưu trữ trước khi xác nhận."], ["Niêm phong là để bảo vệ người và chứng cứ; đừng tự ý vượt qua ranh giới an toàn.", "Bác sẽ liên hệ người phụ trách và ghi lại thời điểm xin phép tiếp cận."], ["Bản gốc là căn cứ quan trọng; mọi bản sao cần ghi rõ nguồn và ngày tạo.", "Mình sẽ lập danh mục trang còn thiếu thay vì tự điền những chỗ chưa biết."], ["Mưa có thể làm thay đổi dấu vết; vì vậy thời gian ghi nhận rất quan trọng.", "Ta hãy mô tả điều nhìn thấy, không suy diễn người nào đã để lại dấu chân."], ["Mẫu chưa rõ thành phần cần được xử lý bởi người có chuyên môn và quy trình an toàn.", "Mình sẽ giữ nguyên mã mẫu để kết quả sau này có thể truy xuất đúng hồ sơ."], ["Một ghi chú cá nhân không tự động trở thành kết luận đã được kiểm chứng.", "Mình sẽ so ngày tháng, người ghi và tài liệu đối chiếu trước khi dùng dữ liệu."], ["Con số chỉ có ý nghĩa khi biết đơn vị, thời điểm và cách đo.", "Ta nên so sánh với dữ liệu nền trước khi giải thích vì sao có chênh lệch."], ["Có tên trong cùng một hồ sơ không có nghĩa là đã chứng minh được trách nhiệm.", "Mình sẽ đánh dấu phần còn là giả thuyết để người đọc không nhầm với sự kiện."], ["Minh cần được lắng nghe trước khi nhận lời khuyên; mỗi người có hoàn cảnh khác nhau.", "Mình có thể đồng hành cùng Minh tìm một người lớn đáng tin để hỗ trợ tiếp."], ["Khôi phục nhà kính chỉ là bước đầu; cộng đồng cần duy trì cách làm an toàn và minh bạch.", "Mình sẽ cùng mọi người đặt lịch kiểm tra định kỳ để bài học không bị lãng quên."]];
  const contextualThirdChoices = [[["Ghi lại điều quan sát được và chọn một việc nhỏ để sửa trước.", "Mực gật đầu: bắt đầu từ việc có thể kiểm chứng sẽ giúp bạn không bị quá tải.", "Mực", "🐈‍⬛"], ["Đề nghị bác cùng lập danh sách những chỗ cần chăm sóc.", "Bác Năm mỉm cười: làm cùng nhau sẽ giúp cháu nhìn thấy nhiều góc độ hơn.", "Bác Năm", "👨‍🌾"]], [["Thử áp dụng một ý trong sách vào việc chăm cây hôm nay.", "Mực nói: hãy ghi lại kết quả để biết điều học được có hiệu quả không.", "Mực", "🐈‍⬛"], ["Xin Linh hướng dẫn cách ghi nhận lần thử nghiệm.", "Linh đáp: ghi chép trung thực là nền tảng của một kết quả đáng tin.", "Linh", "👩‍🔬"]], [["Ghi ba việc quan trọng nhất và ước lượng thời gian cho từng việc.", "Mực khen: một danh sách ngắn, rõ ràng sẽ dễ thực hiện hơn.", "Mực", "🐈‍⬛"], ["Cùng Tí kiểm tra sức chở trước khi chốt lịch giao.", "Tí nói: chuẩn bị đúng năng lực sẽ giúp mình giữ lời hẹn.", "Tí", "🧑‍🌾"]], [["Báo tình hình ngay và đề nghị một mốc cập nhật mới.", "Tí thở phào: biết sớm giúp mọi người chủ động sắp xếp.", "Tí", "🧑‍🌾"], ["Xin bác hỗ trợ phần việc đang vượt quá khả năng của mình.", "Bác Năm đáp: nhờ giúp đỡ đúng lúc cũng là một biểu hiện trách nhiệm.", "Bác Năm", "👨‍🌾"]], [["Tạo bảng phân công để mọi người biết phần việc của nhau.", "Bác Năm nói: rõ việc thì dễ hỗ trợ và không ai bị bỏ quên.", "Bác Năm", "👨‍🌾"], ["Tổ chức một lượt cập nhật ngắn trước khi kết thúc ngày.", "Linh đồng ý: cập nhật đều giúp nhóm phát hiện vướng mắc sớm.", "Linh", "👩‍🔬"]], [["Đưa ra ví dụ cụ thể và hỏi người viết muốn sửa theo cách nào.", "Linh đáp: góp ý có tôn trọng sẽ mở ra cuộc trao đổi tốt hơn.", "Linh", "👩‍🔬"], ["Cùng kiểm tra lại bản báo cáo để thống nhất cách sửa.", "Mực nói: kiểm tra chung giúp phản hồi dựa trên cùng một căn cứ.", "Mực", "🐈‍⬛"]], [["Viết lại thông báo bằng câu ngắn và kiểm tra đủ thông tin.", "Mực gật đầu: người đọc cần hiểu việc cần làm ngay từ lần đầu.", "Mực", "🐈‍⬛"], ["Nhờ Tí đọc thử như người nhận đơn hàng.", "Tí đáp: mình sẽ chỉ ra chỗ nào còn dễ hiểu nhầm.", "Tí", "🧑‍🌾"]], [["So sánh mục tiêu ban đầu với kết quả thực tế.", "Bác Năm nói: nhìn cả điểm tốt và điểm chưa tốt mới rút được kinh nghiệm.", "Bác Năm", "👨‍🌾"], ["Lập một ghi chú để lần sau tránh lặp lại vấn đề.", "Mực khen: bài học được ghi lại sẽ hữu ích cho cả nhóm.", "Mực", "🐈‍⬛"]], [["Mời người có ý kiến khác giải thích căn cứ của họ.", "Mực nói: lắng nghe trước khi phản hồi giúp cuộc trao đổi công bằng hơn.", "Mực", "🐈‍⬛"], ["Đặt các phương án cạnh nhau rồi so sánh bằng tiêu chí chung.", "Linh đáp: cùng một tiêu chí sẽ giúp nhóm quyết định khách quan.", "Linh", "👩‍🔬"]], [["Chọn một thay đổi nhỏ và hẹn ngày đánh giá lại.", "Mực mỉm cười: cải tiến cần được theo dõi chứ không dừng ở lời hứa.", "Mực", "🐈‍⬛"], ["Chia sẻ cách làm hiệu quả để các bạn cùng áp dụng.", "Bác Năm nói: kinh nghiệm tốt sẽ có ích hơn khi được truyền lại.", "Bác Năm", "👨‍🌾"]], [["Kiểm tra dấu xác nhận và đối chiếu nơi lưu trữ bức thư.", "Mực nhắc: nguồn gốc rõ ràng là bước đầu của xác minh.", "Mực", "🐈‍⬛"], ["Ghi lại điều đã biết và điều cần hỏi thêm.", "Bác Tư nói: phân biệt hai phần này giúp ta không vô tình thêm tin đồn.", "Bác Tư", "👨‍🌾"]], [["Ghi nhận hiện trạng và chờ người phụ trách xác nhận.", "Bác Tư nói: an toàn và đúng quy định phải được đặt lên trước.", "Bác Tư", "👨‍🌾"], ["Tìm số liên hệ của người quản lý khu vực.", "Mực đáp: đi đúng quy trình sẽ bảo vệ cả người lẫn hồ sơ.", "Mực", "🐈‍⬛"]], [["Lập danh mục tài liệu theo ngày và đánh mã từng trang.", "Linh nói: cách sắp xếp nhất quán giúp tìm lại tài liệu nhanh hơn.", "Linh", "👩‍🔬"], ["Tạo bản sao làm việc nhưng giữ nguyên bản gốc.", "Mực nhắc: bản gốc cần được bảo toàn để đối chiếu về sau.", "Mực", "🐈‍⬛"]], [["Chụp ảnh vị trí từ khoảng cách an toàn và ghi thời điểm.", "Bác Tư nói: ghi nhận khách quan giúp người khác kiểm tra lại.", "Bác Tư", "👨‍🌾"], ["Đánh dấu khu vực cần người chuyên trách kiểm tra.", "Mực đáp: không làm xáo trộn hiện trường là điều rất quan trọng.", "Mực", "🐈‍⬛"]], [["Ghi mã mẫu, người bàn giao và thời gian tiếp nhận.", "Linh nói: chuỗi bàn giao rõ ràng giúp tránh nhầm lẫn mẫu vật.", "Linh", "👩‍🔬"], ["Đưa mẫu vào danh sách chờ người chuyên môn xử lý.", "Mực nhắc: không tự ý thử mẫu chưa xác định.", "Mực", "🐈‍⬛"]], [["Đánh dấu phần ghi chép là quan sát hay nhận định.", "Linh mỉm cười: phân biệt hai loại thông tin giúp kết luận chính xác hơn.", "Linh", "👩‍🔬"], ["Lập dòng thời gian từ những ghi chú có ngày tháng.", "Mực nói: trình tự rõ sẽ giúp ta nhìn ra điều gì xảy ra trước sau.", "Mực", "🐈‍⬛"]], [["Kiểm tra đơn vị đo và điều kiện thu thập số liệu.", "Linh đáp: đôi khi khác biệt đến từ cách đo chứ không phải bản thân hiện tượng.", "Linh", "👩‍🔬"], ["Đối chiếu nhiều lần đo trước khi đưa ra nhận xét.", "Mực nói: kết luận tốt cần dựa trên nhiều căn cứ phù hợp.", "Mực", "🐈‍⬛"]], [["Gắn nguồn tài liệu cho từng đường nối trong sơ đồ.", "Mực nhắc: người đọc phải lần được từ kết luận về chứng cứ.", "Mực", "🐈‍⬛"], ["Tách riêng phần đã xác nhận và phần cần điều tra thêm.", "Bác Tư nói: sự thận trọng bảo vệ cả người được nhắc đến lẫn độ tin cậy của báo cáo.", "Bác Tư", "👨‍🌾"]], [["Hỏi Minh muốn được lắng nghe hay muốn cùng tìm giải pháp.", "Minh nói nhỏ: cảm ơn vì đã không vội phán xét mình.", "Minh", "🧑"], ["Cùng Minh chọn một người đáng tin để trò chuyện.", "Mực nói: tìm hỗ trợ đúng lúc là một hành động can đảm.", "Mực", "🐈‍⬛"]], [["Lập lịch chăm sóc và phân công người theo dõi nhà kính.", "Linh đáp: duy trì công việc đều đặn sẽ bảo vệ thành quả lâu dài.", "Linh", "👩‍🔬"], ["Chia sẻ bài học và mời cộng đồng góp ý định kỳ.", "Minh mỉm cười: ai cũng có thể góp một phần để khu vườn tốt hơn.", "Minh", "🧑"]]];
  chapters.forEach((chapter, chapterIndex) => {
    chapter.talks.forEach((scene, sceneIndex) => {
      const extra = dialogueAdditions[chapterIndex]?.[sceneIndex];
      if (extra) scene.text += ' ' + extra;
      const choice = contextualThirdChoices[chapterIndex]?.[sceneIndex];
      if (choice && scene.options && scene.options[2]) {
        Object.assign(scene.options[2], {
          label: choice[0], accepted: true, metric: 'community',
          playerText: choice[0], reply: choice[1], replySpeaker: choice[2], replyAvatar: choice[3]
        });
      }
    });
  });

  let data;
  try{
    const old=safeParse(STORY,{});
    data={unlocked:0,completed:[],answered:[],selected:0,dialogueProgress:{},metrics:{evidence:0,teamwork:0,community:0},ending:'',...old};
  }catch(e){data={unlocked:0,completed:[],answered:[],selected:0,dialogueProgress:{},metrics:{evidence:0,teamwork:0,community:0},ending:''};}
  data.completed=Array.isArray(data.completed)?data.completed:[];
  data.answered=Array.isArray(data.answered)?data.answered:[];
  data.dialogueProgress=data.dialogueProgress&&typeof data.dialogueProgress==='object'?data.dialogueProgress:{};
  data.metrics={evidence:0,teamwork:0,community:0,...(data.metrics||{})};
  data.unlocked=Math.max(0,Math.min(chapters.length-1,Number(data.unlocked)||0));
  if(data.completed.length)data.unlocked=Math.max(data.unlocked,Math.min(chapters.length-1,Math.max(...data.completed)+1));
  const save=()=>localStorage.setItem(STORY,JSON.stringify(data));
  let typingTimer=null;
  function clearTyping(){if(typingTimer){clearInterval(typingTimer);typingTimer=null;}}
  function notify(t){const el=$('toast');if(!el)return;el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600);}
  function status(i){return data.completed.includes(i)?'done':i<=data.unlocked?'open':'locked';}
  function dlg(i){if(!data.dialogueProgress[i])data.dialogueProgress[i]={step:0,phase:'prompt',choice:null};return data.dialogueProgress[i];}
  function dialogueCount(i){return Math.min(chapters[i].talks.length,dlg(i).step);}
  function missionCount(i){const c=chapters[i],d=dialogueCount(i),answered=data.answered.includes(i),eligible=d>=c.talks.length&&answered,ready=!!c.check(game());return Math.min(4,d+(answered?1:0)+(data.completed.includes(i)?1:(eligible&&ready?1:0)));}
  function typeInto(el,text,speed=22,done=()=>{}){
    clearTyping();if(!el){done();return;}const full=String(text||'');let n=0;el.textContent='';typingTimer=setInterval(()=>{n++;el.textContent=full.slice(0,n);if(n>=full.length){clearTyping();done();}},speed);
  }
  function completeTyping(texts){clearTyping();texts.forEach(([id,text])=>{const el=$(id);if(el)el.textContent=text;});const choices=$('muc-scene-choices');if(choices)choices.hidden=false;const next=$('muc-next-talk');if(next)next.hidden=false;const skip=$('muc-skip-typing');if(skip)skip.hidden=true;}
  function renderList(){
    const list=$('muc-chapter-list');if(!list)return;
    const actNames=['HỒI I · NHỮNG HẠT MẦM SỬA ĐỔI','HỒI II · HỌC HỎI VÀ PHỐI HỢP','HỒI III · HỒ SƠ NHÀ KÍNH SỐ 7','HỒI IV · ĐIỀU TRA VÀ KHÔI PHỤC','HỒI V · SỰ THẬT CUỐI CÙNG'];
    list.innerHTML=actNames.map((name,act)=>{
      const items=chapters.map((c,i)=>({c,i})).filter(x=>x.c.act===act+1);
      return `<div class="muc-act-group"><div class="muc-act-title">${name}</div>${items.map(({c,i})=>{const st=status(i);return `<button type="button" class="muc-chapter-item ${st} ${data.selected===i?'selected':''}" data-chapter="${i}" ${st==='locked'?'disabled':''}><span class="muc-chapter-number">${String(i+1).padStart(2,'0')}</span><span><b>${c.title}</b><small>${c.skill}</small></span><strong>${st==='done'?'✓':st==='locked'?'🔒':'›'}</strong></button>`}).join('')}</div>`;
    }).join('');
    list.querySelectorAll('[data-chapter]').forEach(b=>b.addEventListener('click',()=>{clearTyping();data.selected=+b.dataset.chapter;save();render();}));
  }
  function objectiveHtml(i,c){
    const d=dialogueCount(i),answered=data.answered.includes(i),ready=!!c.check(game()),completed=data.completed.includes(i);
    const labels=['Trò chuyện với nhân vật 1','Trao đổi với nhân vật 2','Câu hỏi kiến thức','Thử thách thực tế'];
    const done=[d>=1,d>=2,answered,completed||(d>=c.talks.length&&answered&&ready)];
    return `<div class="muc-objectives"><div class="muc-objectives-head"><b>🎯 4 mục tiêu của chương</b><span>${missionCount(i)}/4 hoàn thành</span></div><div class="muc-objective-grid">${labels.map((label,n)=>`<div class="muc-objective ${done[n]?'is-done':''}"><span>${done[n]?'✓':n+1}</span><small>${label}</small></div>`).join('')}</div></div>`;
  }
  function renderCinematic(i,c){
    const p=dlg(i),done=data.completed.includes(i),step=Math.min(p.step,c.talks.length-1),talkData=c.talks[step],phase=p.phase||'prompt',choice=phase==='reply'?talkData.options[p.choice]:null;
    if(done||p.step>=c.talks.length)return `<div class="muc-cinematic muc-cinematic-done"><div class="muc-scene-sky"><span>✨</span><span>🍃</span><span>🌟</span></div><div class="muc-scene-people"><div class="muc-character npc-character is-happy"><span class="muc-character-art">🐈‍⬛</span><b>Mực</b><small>Thủ thư</small></div><div class="muc-scene-book">📖</div><div class="muc-character player-character is-happy"><span class="muc-character-art">🧑‍🌾</span><b>Bạn</b><small>Người làm vườn</small></div></div><div class="muc-scene-caption">${done?'🏅 Chương đã hoàn thành. Câu chuyện vẫn được lưu trong nhật ký.':'✨ Hai cuộc trò chuyện đã hoàn tất. Hãy trả lời câu hỏi và thực hiện thử thách của chương.'}</div></div>`;
    const currentSpeaker=phase==='reply'?'Bạn':talkData.speaker;
    const npcAvatar=talkData.avatar||'🐈‍⬛';
    let responseMarkup='';
    if(phase==='reply'&&choice){responseMarkup=`<div class="muc-dialogue-reply player-reply"><div class="muc-reply-avatar">🧑‍🌾<small>Bạn</small></div><div class="muc-speech-bubble player-bubble"><b>Bạn nói</b><p id="muc-player-line"></p></div></div><div class="muc-dialogue-reply npc-reply"><div class="muc-reply-avatar">${choice.replyAvatar||'🐈‍⬛'}<small>${choice.replySpeaker||'Mực'}</small></div><div class="muc-speech-bubble npc-bubble"><b>${choice.replySpeaker||'Mực'}</b><p id="muc-reply-line"></p></div></div>`;}
    else{responseMarkup=`<div class="muc-dialogue-reply npc-reply"><div class="muc-reply-avatar">${npcAvatar}<small>${talkData.speaker}</small></div><div class="muc-speech-bubble npc-bubble"><b>${talkData.speaker}</b><p id="muc-npc-line"></p></div></div>`;}
    const options=phase==='prompt'?`<div class="muc-scene-choices" id="muc-scene-choices" hidden>${talkData.options.map((o,n)=>`<button type="button" class="muc-scene-choice" data-talk-choice="${n}">${String.fromCharCode(65+n)}. ${o.label}</button>`).join('')}</div>`:`<button type="button" class="primary muc-next-talk" id="muc-next-talk" hidden>${step===c.talks.length-1?'Hoàn tất hội thoại →':'Tiếp tục câu chuyện →'}</button>`;
    return `<section class="muc-cinematic ${phase==='reply'?'player-speaking':''}" aria-label="Cảnh hội thoại chương ${i+1}"><div class="muc-scene-sky"><span class="muc-scene-cloud cloud-one">☁️</span><span class="muc-scene-cloud cloud-two">☁️</span><span class="muc-scene-firefly firefly-one">✦</span><span class="muc-scene-firefly firefly-two">✧</span><span class="muc-scene-leaf leaf-one">🍃</span><span class="muc-scene-leaf leaf-two">🍂</span></div><div class="muc-scene-topline"><span>🎬 CẢNH ${step+1}/${c.talks.length} · ${c.sceneName||'HỘI THOẠI TƯƠNG TÁC'}</span><span>${phase==='prompt'?'NPC đang trò chuyện':'Bạn đang trả lời'}</span></div><div class="muc-scene-people"><div class="muc-character npc-character ${phase==='prompt'?'is-speaking':'is-listening'} mood-${talkData.mood||'calm'}"><span class="muc-character-art">${npcAvatar}</span><b>${talkData.speaker}</b><small>${phase==='prompt'?'Đang nói':'Đang lắng nghe'}</small></div><div class="muc-scene-prop">${step%2===0?'📜':'🔎'}</div><div class="muc-character player-character ${phase==='reply'?'is-speaking':'is-listening'}"><span class="muc-character-art">🧑‍🌾</span><b>Bạn</b><small>${phase==='reply'?'Đang trả lời':'Đang suy nghĩ'}</small></div></div><div class="muc-scene-dialogue">${responseMarkup}</div><button type="button" class="muc-skip-typing" id="muc-skip-typing">Hiện toàn bộ lời thoại</button>${options}<div class="muc-scene-feedback" id="muc-scene-feedback" aria-live="polite"></div></section>`;
  }
  function renderDetail(el){
    const i=data.selected,c=chapters[i],done=data.completed.includes(i),answered=data.answered.includes(i),s=game(),ready=c.check(s),p=dlg(i),dialogueReady=p.step>=c.talks.length;
    const dCount=dialogueCount(i);
    el.innerHTML=`<div class="muc-detail-top"><span>📖 CHƯƠNG ${i+1}/20 · HỒI ${c.act}/5</span><span>${done?'ĐÃ HOÀN THÀNH':dialogueReady?'ĐANG THỰC HÀNH':'ĐANG TRÒ CHUYỆN'}</span></div><h3>${c.title}</h3><p class="muc-skill-pill">🎓 Kỹ năng: ${c.skill}</p><p class="muc-chapter-intro">${c.scene}</p>${objectiveHtml(i,c)}${renderCinematic(i,c)}<div class="muc-question ${dialogueReady?'':'is-locked'}"><b>📚 Câu hỏi kiến thức</b><p>${c.q}</p>${dialogueReady?`<div class="muc-answer-list">${c.a.map((v,n)=>`<button type="button" class="muc-answer ${answered?'locked-answer':''}" data-answer="${n}" ${answered||done?'disabled':''}>${String.fromCharCode(65+n)}. ${v}</button>`).join('')}</div>`:'<div class="muc-locked-note">🔒 Hãy hoàn thành 2 lượt hội thoại để mở câu hỏi của chương.</div>'}<p class="muc-feedback" id="muc-story-feedback">${answered?'✓ Bạn đã trả lời đúng. Hãy thực hiện việc thực hành để hoàn tất chương.':dialogueReady?'Chọn đáp án phù hợp nhất.':'Câu hỏi sẽ mở sau khi hoàn thành hội thoại.'}</p></div><div class="muc-practice"><b>🌱 Thử thách thực tế</b><p>${c.task}</p><small class="${ready?'practice-ready':''}">${ready?'✓ ':'○ '}${c.taskText}</small><button type="button" class="primary" id="muc-check-practice" ${!dialogueReady||!answered||!ready||done?'disabled':''}>${done?'Đã nhận phần thưởng':'Kiểm tra và hoàn thành chương'}</button></div>${done?`<div class="muc-complete-banner">🏅 Chương hoàn thành! Nhận +15 xu và +5 điểm nghiên cứu.</div>`:''}${data.ending&&i===19?`<div class="muc-ending-card"><b>🏆 KẾT THÚC CHIẾN DỊCH</b><h4>${data.ending}</h4><p>${endingDescription(data.ending)}</p><small>Điểm lựa chọn · Chứng cứ: ${data.metrics.evidence} · Đồng hành: ${data.metrics.teamwork} · Cộng đồng: ${data.metrics.community}</small></div>`:''}`;
    el.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>answer(i,+b.dataset.answer)));
    el.querySelectorAll('[data-talk-choice]').forEach(b=>b.addEventListener('click',()=>chooseTalk(i,+b.dataset.talkChoice)));
    const check=$('muc-check-practice');if(check)check.addEventListener('click',()=>complete(i));
    const next=$('muc-next-talk');if(next)next.addEventListener('click',()=>nextTalk(i));
    const skip=$('muc-skip-typing');if(skip)skip.addEventListener('click',skipTyping);
    if(!done&&p.step<c.talks.length)startTyping(i,c,p);
  }
  function startTyping(i,c,p){
    clearTyping();const t=c.talks[p.step];if(!t)return;
    const skip=$('muc-skip-typing');if(skip)skip.hidden=false;
    const choices=$('muc-scene-choices');if(choices)choices.hidden=true;
    const next=$('muc-next-talk');if(next)next.hidden=true;
    if(p.phase==='prompt'){
      typeInto($('muc-npc-line'),t.text,20,()=>{if($('muc-scene-choices'))$('muc-scene-choices').hidden=false;if($('muc-skip-typing'))$('muc-skip-typing').hidden=true;});
    }else{
      const opt=t.options[p.choice];if(!opt)return;
      typeInto($('muc-player-line'),opt.playerText||opt.label,18,()=>{
        typeInto($('muc-reply-line'),opt.reply||'Mực gật đầu và ghi nhận câu trả lời của bạn.',20,()=>{if($('muc-next-talk'))$('muc-next-talk').hidden=false;if($('muc-skip-typing'))$('muc-skip-typing').hidden=true;});
      });
    }
  }
  function skipTyping(){
    const i=data.selected,c=chapters[i],p=dlg(i),t=c.talks[p.step];if(!t)return;
    if(p.phase==='prompt'){completeTyping([['muc-npc-line',t.text]]);}
    else{const o=t.options[p.choice];completeTyping([['muc-player-line',o.playerText||o.label],['muc-reply-line',o.reply||'Mực gật đầu.']]);}
  }
  function chooseTalk(i,n){
    if(i!==data.selected||data.completed.includes(i))return;
    const c=chapters[i],p=dlg(i),t=c.talks[p.step],o=t&&t.options[n];if(!o||p.phase!=='prompt')return;
    const feedback=$('muc-scene-feedback');
    if(!o.accepted){if(feedback)feedback.textContent='💡 '+o.feedback+' Hãy suy nghĩ và thử lựa chọn khác.';return;}
    p.choice=n;p.phase='reply';data.metrics[o.metric]=(Number(data.metrics[o.metric])||0)+1;save();renderDetail($('muc-chapter-detail'));
  }
  function nextTalk(i){
    if(i!==data.selected||data.completed.includes(i))return;
    const c=chapters[i],p=dlg(i);if(p.phase!=='reply')return;
    p.step++;p.phase='prompt';p.choice=null;save();renderDetail($('muc-chapter-detail'));renderList();
  }
  function answer(i,n){
    if(i!==data.unlocked||data.completed.includes(i)||data.answered.includes(i)||dlg(i).step<chapters[i].talks.length)return;
    const c=chapters[i],feedback=$('muc-story-feedback');
    if(n!==c.c){if(feedback)feedback.textContent='Chưa chính xác. '+c.why+' Hãy đọc lại và thử lựa chọn khác nhé.';return;}
    data.answered.push(i);save();if(feedback)feedback.textContent='✓ Chính xác! '+c.why+' Bây giờ hãy thực hiện thử thách trong nông trại.';renderDetail($('muc-chapter-detail'));renderList();
  }
  function endingDescription(name){
    if(name==='Người gieo mầm tri thức')return 'Bạn đã cân bằng việc tìm chứng cứ, đồng hành với mọi người và đóng góp cho cộng đồng. Nhà kính số 7 trở thành nơi học hỏi và cùng nhau sửa đổi.';
    if(name==='Người quan sát')return 'Bạn nổi bật ở khả năng kiểm tra dữ kiện, đối chiếu hồ sơ và phân biệt sự thật với suy đoán.';
    if(name==='Người kết nối')return 'Bạn đã lắng nghe, phối hợp và giúp các nhân vật tìm được tiếng nói chung.';
    return 'Bạn tập trung khôi phục môi trường sống và biến bài học thành hành động thiết thực cho cộng đồng.';
  }
  function determineEnding(){
    const m=data.metrics;
    if(m.evidence>=8&&m.teamwork>=8&&m.community>=8)return 'Người gieo mầm tri thức';
    const ranked=[['Người quan sát',m.evidence],['Người kết nối',m.teamwork],['Người khôi phục cộng đồng',m.community]].sort((a,b)=>b[1]-a[1]);
    return ranked[0][0];
  }
  function complete(i){
    if(i!==data.unlocked||data.completed.includes(i))return;
    const c=chapters[i],s=game();
    if(dlg(i).step<c.talks.length){notify('Hãy hoàn thành 2 lượt hội thoại trước.');return;}
    if(!data.answered.includes(i)){notify('Bạn cần trả lời đúng câu hỏi kiến thức.');return;}
    if(!c.check(s)){notify('Bạn chưa hoàn thành phần thực hành của chương.');renderDetail($('muc-chapter-detail'));return;}
    s.coins=(+s.coins||0)+15;s.researchPoints=(+s.researchPoints||0)+5;s.labLevel=Math.min(5,Math.max(+s.labLevel||1,1+Math.floor(s.researchPoints/30)));s.lastAction='Hoàn thành chương '+(i+1)+' của Mực';localStorage.setItem(GAME,JSON.stringify(s));
    data.completed.push(i);if(i<chapters.length-1)data.unlocked=i+1;else data.ending=determineEnding();data.selected=Math.min(i+1,chapters.length-1);save();window.dispatchEvent(new Event('aeCayKheExternalUpdate'));render();notify('Hoàn thành chương '+(i+1)+'! +15 xu, +5 điểm nghiên cứu.');
  }
  function render(){
    const list=$('muc-chapter-list'),detail=$('muc-chapter-detail');if(!list||!detail)return;
    const done=data.completed.length,percent=Math.round(done/chapters.length*100);
    if($('muc-journey-count'))$('muc-journey-count').textContent=done+'/'+chapters.length+' chương hoàn thành';
    if($('muc-journey-percent'))$('muc-journey-percent').textContent=percent+'%';
    if($('muc-journey-bar'))$('muc-journey-bar').style.width=percent+'%';
    renderList();renderDetail(detail);
  }
  function init(){
    if(!$('muc-journey'))return;
    const kicker=$('muc-journey-kicker');if(kicker)kicker.textContent='CỐT TRUYỆN GIÁO DỤC · 20 CHƯƠNG · 80 MỤC TIÊU';
    if(!data.completed.length&&!data.answered.length&&!data.dialogueProgress[0]){data.unlocked=0;data.selected=0;save();}
    render();
    window.addEventListener('aeCayKheStateUpdated',()=>render());
    window.addEventListener('aeCayKheExternalUpdate',()=>render());
    setInterval(()=>{
      const i=data.selected,c=chapters[i],btn=$('muc-check-practice');if(!c||!btn||data.completed.includes(i))return;
      const ready=c.check(game()),eligible=dlg(i).step>=c.talks.length&&data.answered.includes(i);
      btn.disabled=!(ready&&eligible);
      const small=$('muc-chapter-detail')?.querySelector('.muc-practice small');if(small){small.className=ready?'practice-ready':'';small.textContent=(ready?'✓ ':'○ ')+c.taskText;}
      const card=$('muc-chapter-detail')?.querySelector('.muc-objectives');if(card){const count=missionCount(i);const label=card.querySelector('.muc-objectives-head span');if(label)label.textContent=count+'/4 hoàn thành';const states=[dlg(i).step>=1,dlg(i).step>=2,data.answered.includes(i),data.completed.includes(i)||(dlg(i).step>=c.talks.length&&data.answered.includes(i)&&ready)];card.querySelectorAll('.muc-objective').forEach((el,n)=>{el.classList.toggle('is-done',!!states[n]);const mark=el.querySelector('span');if(mark)mark.textContent=states[n]?'✓':String(n+1);});}
    },2500);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
